create or replace function private.is_staff() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.user_roles where user_id=(select auth.uid()) and role in ('support','admin')) $$;
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.user_roles where user_id=(select auth.uid()) and role='admin') $$;
create or replace function private.is_conversation_member(target_conversation_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.conversation_members where conversation_id=target_conversation_id and user_id=(select auth.uid())) $$;
revoke all on schema private from public; grant usage on schema private to authenticated;
grant execute on function private.is_staff() to authenticated; grant execute on function private.is_admin() to authenticated;
grant execute on function private.is_conversation_member(uuid) to authenticated;

do $$ declare t text; begin foreach t in array array[
'profiles','user_roles','customer_profiles','provider_profiles','provider_verification_documents','service_categories','services','provider_services','provider_availability','provider_service_areas','addresses','bookings','booking_status_history','booking_attachments','booking_quotes','quote_items','change_orders','change_order_items','payments','payment_transactions','refunds','provider_earnings','provider_payouts','conversations','conversation_members','messages','message_attachments','reviews','review_responses','favourites','notifications','notification_preferences','promo_codes','promo_code_uses','wallets','wallet_transactions','disputes','dispute_evidence','support_tickets','support_messages','provider_portfolio','provider_certifications','user_reports','admin_roles','admin_permissions','admin_role_assignments','audit_logs','app_settings'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;

create policy profiles_own_select on public.profiles for select to authenticated using(id=(select auth.uid()));
create policy profiles_public_provider_select on public.profiles for select to anon,authenticated using(exists(select 1 from public.provider_profiles p where p.id=profiles.id and p.is_published and p.deleted_at is null));
create policy profiles_own_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy roles_own_select on public.user_roles for select to authenticated using(user_id=(select auth.uid()));
create policy customer_own_all on public.customer_profiles for all to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
