create policy services_public_read on public.services for select to anon,authenticated using(is_active and deleted_at is null);
create policy providers_public_read on public.provider_profiles for select to anon,authenticated using(is_published and deleted_at is null);
create policy providers_own_update on public.provider_profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
