create policy provider_areas_own_write on public.provider_service_areas for all to authenticated using(provider_id=(select auth.uid())) with check(provider_id=(select auth.uid()));
create policy addresses_own_all on public.addresses for all to authenticated using(customer_id=(select auth.uid())) with check(customer_id=(select auth.uid()));
create policy portfolio_public_read on public.provider_portfolio for select to anon,authenticated using(exists(select 1 from public.provider_profiles p where p.id=provider_id and p.is_published));
create policy portfolio_own_write on public.provider_portfolio for all to authenticated using(provider_id=(select auth.uid())) with check(provider_id=(select auth.uid()));
create policy certifications_public_read on public.provider_certifications for select to anon,authenticated using(is_public and exists(select 1 from public.provider_profiles p where p.id=provider_id and p.is_published));
create policy certifications_own_read on public.provider_certifications for select to authenticated using(provider_id=(select auth.uid()));
create policy verification_owner_read on public.provider_verification_documents for select to authenticated using(provider_id=(select auth.uid()) or private.is_staff());
create policy verification_owner_insert on public.provider_verification_documents for insert to authenticated with check(provider_id=(select auth.uid()));
create policy bookings_participant_read on public.bookings for select to authenticated using(customer_id=(select auth.uid()) or provider_id=(select auth.uid()) or private.is_staff());
create policy bookings_customer_insert on public.bookings for insert to authenticated with check(customer_id=(select auth.uid()));
create policy booking_history_participant_read on public.booking_status_history for select to authenticated using(exists(select 1 from public.bookings b where b.id=booking_id and (b.customer_id=(select auth.uid()) or b.provider_id=(select auth.uid()))) or private.is_staff());
create policy booking_attachments_participant on public.booking_attachments for select to authenticated using(exists(select 1 from public.bookings b where b.id=booking_id and (b.customer_id=(select auth.uid()) or b.provider_id=(select auth.uid()))) or private.is_staff());
create policy booking_attachments_insert on public.booking_attachments for insert to authenticated with check(uploader_id=(select auth.uid()) and exists(select 1 from public.bookings b where b.id=booking_id and (b.customer_id=(select auth.uid()) or b.provider_id=(select auth.uid()))));
create policy conversations_member_read on public.conversations for select to authenticated using(private.is_conversation_member(id) or private.is_staff());
create policy conversation_members_member_read on public.conversation_members for select to authenticated using(private.is_conversation_member(conversation_id) or private.is_staff());
create policy messages_member_read on public.messages for select to authenticated using(private.is_conversation_member(conversation_id) or private.is_staff());
create policy messages_member_insert on public.messages for insert to authenticated with check(sender_id=(select auth.uid()) and private.is_conversation_member(conversation_id));
create policy reviews_public_read on public.reviews for select to anon,authenticated using(deleted_at is null);
create policy reviews_completed_booking_insert on public.reviews for insert to authenticated with check(customer_id=(select auth.uid()) and exists(select 1 from public.bookings b where b.id=booking_id and b.customer_id=(select auth.uid()) and b.provider_id=provider_id and b.status='completed'));
create policy review_responses_public_read on public.review_responses for select to anon,authenticated using(true);
create policy favourites_own_all on public.favourites for all to authenticated using(customer_id=(select auth.uid())) with check(customer_id=(select auth.uid()));
create policy notifications_own_read on public.notifications for select to authenticated using(user_id=(select auth.uid()));
