create policy disputes_participant_read on public.disputes for select to authenticated using(opened_by=(select auth.uid()) or private.is_staff());
create policy disputes_owner_insert on public.disputes for insert to authenticated with check(opened_by=(select auth.uid()));
create policy support_ticket_owner_read on public.support_tickets for select to authenticated using(requester_id=(select auth.uid()) or private.is_staff());
