create policy admin_only_roles on public.admin_roles for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy admin_only_permissions on public.admin_permissions for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy admin_only_assignments on public.admin_role_assignments for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy admin_only_audit on public.audit_logs for select to authenticated using(private.is_admin());
create policy public_active_promos on public.promo_codes for select to authenticated using(is_active and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>now()));
