insert into storage.buckets(id,name,public) values('avatars','avatars',true),('provider-portfolios','provider-portfolios',true),('booking-attachments','booking-attachments',false),('verification-documents','verification-documents',false),('dispute-evidence','dispute-evidence',false) on conflict(id) do nothing;
create policy public_media_read on storage.objects for select to anon,authenticated using(bucket_id in ('avatars','provider-portfolios'));
create policy own_avatar_write on storage.objects for insert to authenticated with check(bucket_id='avatars' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy provider_portfolio_write on storage.objects for insert to authenticated with check(bucket_id='provider-portfolios' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy private_user_uploads on storage.objects for insert to authenticated with check(bucket_id in ('booking-attachments','verification-documents','dispute-evidence') and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy private_user_reads on storage.objects for select to authenticated using(bucket_id in ('booking-attachments','verification-documents','dispute-evidence') and ((storage.foldername(name))[1]=(select auth.uid())::text or private.is_staff()));
